: sq-dist ( x y -- d )
  dup * swap dup * + ;

: pt-dist ( p -- d )
  dup 2* dup >r  ch@  r> 1+ ch@  sq-dist  nip ;

: pt-y ( p -- y )
  dup 2* 1+ ch@  nip ;

variable kc-k

variable kd0
variable kd1

: load-dists ( -- )
  0 pt-dist kd0 !  1 pt-dist kd1 ! ;

: closer-y ( -- y )
  load-dists
  kd0 @ kd1 @ > if  1 pt-y  else  0 pt-y  then ;

: farther-y ( -- y )
  load-dists
  kd0 @ kd1 @ > if  0 pt-y  else  1 pt-y  then ;

: k-closest ( k -- sum )
  kc-k !
  closer-y
  kc-k @ 2 = if  farther-y +  then ;

